import{_ as h,C as c,o as r,c as p,a2 as o,b as i,w as t,a,E as d,a8 as l,j as s}from"./chunks/framework.DnwFWYke.js";const y=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"docs/architecture.md","filePath":"docs/architecture.md"}'),u={name:"docs/architecture.md"};function m(g,e,f,b,v,w){const n=c("Mermaid");return r(),p("div",null,[e[5]||(e[5]=o('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Coach Poulpy is <strong>local-first</strong>: the mobile app holds the whole domain model and runs alone as a guest on family phones, and the server and website join later as a sync and sharing layer over the same model. One Kotlin Multiplatform core owns the domain, the workout engine and the database on Android and iOS, so the two apps cannot drift apart. The decisions behind this are recorded as <a href="https://github.com/tkint/coach-poulpy/tree/main/docs/adr/" target="_blank" rel="noreferrer">ADRs</a>; the words are defined in the <a href="./../CONTEXT">glossary</a>.</p><h2 id="decisions-for-v1" tabindex="-1">Decisions for v1 <a class="header-anchor" href="#decisions-for-v1" aria-label="Permalink to &quot;Decisions for v1&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>v1</th><th>Later</th></tr></thead><tbody><tr><td>Audience</td><td>The family, as guests</td><td>A public app</td></tr><tr><td>Accounts</td><td>Guest mode, all data on the phone; email and password, Sign in with Apple and Google when the server arrives</td><td>Guest data moves into a new account on sign-up</td></tr><tr><td>Website</td><td>Needs an account; plans, manages, reviews and runs guided sessions without devices</td><td></td></tr><tr><td>Catalog</td><td>Built-in and curated, with simple images; no user-created exercises</td><td>User-created exercises with duplicate detection</td></tr><tr><td>Workouts</td><td>Circuit or sets, in parts (warm-up, work, cool down); strength, cardio, rehab, stretching and treadmill walks and runs</td><td>Outdoor running, walking, swimming with GPS; workout tags</td></tr><tr><td>Treadmill</td><td>FTMS read and record, alone or checked against a planned workout</td><td>Speed and incline control per phase</td></tr><tr><td>Progression</td><td>Every week written out by hand</td><td>Rules from recognised protocols, driven by sessions and goals</td></tr><tr><td>Sharing</td><td>Save to library synced with the author or as a copy</td><td></td></tr><tr><td>Coaching</td><td>Athlete invites a coach and can revoke; coach edits assigned plans and comments on sessions</td><td></td></tr><tr><td>Export</td><td>.FIT file for Garmin Connect and Strava; optional Apple Health and Health Connect</td><td>Direct Garmin and Strava links</td></tr><tr><td>Language and units</td><td>French and English, metric and imperial: distances, speeds and weights follow the setting (weights are stored in kilograms and shown in pounds in imperial), except a distance picked in whole miles or kilometres, which keeps the unit it was picked in</td><td></td></tr><tr><td>Hosting</td><td>The whole stack runs on the dev computer; the server deploys with Docker to one server (<a href="./adr/0019-the-server-runs-with-docker-compose-on-one-server">ADR 0019</a>)</td><td>A bigger machine or a managed database when it runs short</td></tr></tbody></table><h2 id="delivery-phases" tabindex="-1">Delivery phases <a class="header-anchor" href="#delivery-phases" aria-label="Permalink to &quot;Delivery phases&quot;">​</a></h2>',5)),(r(),i(l,null,{default:t(()=>[d(n,{id:"mermaid-161",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20p1%5B%221%20%C2%B7%20Guest%20app%3Cbr%2F%3Ecatalog%2C%20builder%2C%20player%2C%3Cbr%2F%3Eplans%2C%20history%2C%20FIT%20export%22%5D%0A%20%20%20%20p2%5B%222%20%C2%B7%20Treadmill%3Cbr%2F%3EFTMS%20recording%2C%3Cbr%2F%3Efree%20or%20matched%20to%20a%20plan%22%5D%0A%20%20%20%20p3%5B%223%20%C2%B7%20Accounts%20and%20sync%3Cbr%2F%3Eserver%2C%20Postgres%2C%20sign-in%2C%3Cbr%2F%3Epush%20and%20pull%20sync%22%5D%0A%20%20%20%20p4%5B%224%20%C2%B7%20Website%3Cbr%2F%3Eplan%2C%20review%20and%20run%3Cbr%2F%3Eguided%20sessions%22%5D%0A%20%20%20%20p5%5B%225%20%C2%B7%20Sharing%20and%20coaching%3Cbr%2F%3Elibrary%20sync%20or%20copy%2C%3Cbr%2F%3Ecoach%20links%2C%20comments%22%5D%0A%20%20%20%20p1%20--%3E%20p3%20--%3E%20p4%20--%3E%20p5%0A%20%20%20%20p2%20-.%20alongside%20.-%20p1%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=o('<p>Each phase adds a layer without reworking the one below it, because the domain, engine and storage are already shared. Phase 2 runs alongside phase 1 because the treadmill link was the riskiest piece. GitHub milestones follow these phases.</p><h2 id="domain-model" tabindex="-1">Domain model <a class="header-anchor" href="#domain-model" aria-label="Permalink to &quot;Domain model&quot;">​</a></h2><p>Every workout shares the same concepts, whatever its format. Planned content is versioned and immutable per version, so a session always points at the exact version it followed, a synced library entry follows the latest version, and a copy forks from one.</p><table tabindex="0"><thead><tr><th>Concept</th><th>What it holds</th></tr></thead><tbody><tr><td>Exercise</td><td>Stable slug, names in French and English, movement pattern, muscle groups, equipment needs (each a list of alternatives) and optional equipment, measurement (reps, time, distance, hold), per-side flag, images, instruction steps</td></tr><tr><td>Workout</td><td>Name, format (circuit or sets), parts (an optional warm-up, one or more work parts, an optional cool down) each holding a tree of steps, estimated duration, tags</td></tr><tr><td>Step</td><td>An exercise step (exercise, prescription, and a role: exercise or recover), a group (sequence, superset, circuit, interval set with rounds), or a rest</td></tr><tr><td>Prescription</td><td>Sets, and per set a target (reps, duration, distance, hold), an optional load, intensity (RPE, speed, incline, heart rate zone), tempo, and rest before the next set</td></tr><tr><td>Plan</td><td>Name, goal, weeks of days, each day holding zero or more workouts</td></tr><tr><td>Enrollment</td><td>A person following a plan version from a start date, with one calendar entry per scheduled workout (planned, done, skipped, moved)</td></tr><tr><td>Goal</td><td>A measurable target with an optional deadline, computed from sessions</td></tr><tr><td>Session</td><td>One workout actually done: start and end, source (guided, free, device only), optional link to the planned workout version and calendar entry, set results, samples, notes, effort and pain</td></tr></tbody></table><p>Statistics are derived, never typed in. <code>core/stats</code> computes metrics from sessions: personal records, weekly load and goal progress all come from the same computation, on the phone for guests and on the server for accounts.</p><p>Sharing and coaching add three small concepts: a library entry (synced or copy), a coach link (status, revocation date) and a comment attached to a session, a set result or a calendar entry.</p><h2 id="formats-parts-and-the-engine" tabindex="-1">Formats, parts and the engine <a class="header-anchor" href="#formats-parts-and-the-engine" aria-label="Permalink to &quot;Formats, parts and the engine&quot;">​</a></h2><p>A workout&#39;s format is chosen when it is created (<a href="./adr/0013-workouts-have-a-format-not-a-type">ADR 0013</a>):</p><table tabindex="0"><thead><tr><th>Format</th><th>Built as</th><th>An exercise holds</th></tr></thead><tbody><tr><td>Circuit</td><td>Rounds through several exercises: a repeat around them</td><td>One set: reps, time or hold and a load; a walk or run has a duration and an intensity</td></tr><tr><td>Sets</td><td>One exercise at a time, all its sets, then the next; repeats for supersets</td><td>Its sets, each with a target and load, and the rest between sets</td></tr></tbody></table>',9)),(r(),i(l,null,{default:t(()=>[d(n,{id:"mermaid-300",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20workout%5B%22Workout%3Cbr%2F%3Eformat%20and%20version%22%5D%20--%3E%20parts%5B%22Parts%3Cbr%2F%3Ewarm-up%20%C2%B7%20work%20%C2%B7%20cool%20down%22%5D%0A%20%20%20%20parts%20--%3E%20steps%5B%22Steps%3Cbr%2F%3Eexercise%20%C2%B7%20group%20%C2%B7%20rest%22%5D%0A%20%20%20%20steps%20--%3E%20compiler%5B%22Timeline%20compiler%22%5D%0A%20%20%20%20compiler%20--%3E%20timeline%5B%22Timeline%3Cbr%2F%3Eflat%20run%20of%20Work%20and%20Rest%20Phases%22%5D%0A%20%20%20%20timeline%20--%3E%20session%5B%22Session%3Cbr%2F%3Eengine%20state%20machine%22%5D%0A%20%20%20%20session%20--%3E%7Cappends%7C%20events%5B%22Session%20events%3Cbr%2F%3Eappend-only%20log%22%5D%0A%20%20%20%20events%20--%3E%7Cfolded%20into%7C%20session%0A%20%20%20%20session%20--%3E%20state%5B%22Session%20state%22%5D%0A%20%20%20%20state%20--%3E%20ui%5B%22App%20renders%20state%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=s("p",null,'How a step finishes comes from its target alone: a time or a hold runs a timer; reps, a distance (unless a treadmill reports it) or "until button press" wait for a tap.',-1)),e[8]||(e[8]=s("p",null,"The clock is injected, so tests never wait; each platform turns cues (3-2-1, switch sides, next exercise) into sound, vibration and text. A killed app resumes from the event log: Open restores a session paused at its last event (guided sessions in the player, Live recordings in Live); Discard deletes it. A session closed without finishing ends at its last event and keeps its totals.",-1)),e[9]||(e[9]=s("p",null,[a("The shared engine runs on each platform ("),s("a",{href:"./adr/0002-one-kotlin-multiplatform-core"},"ADR 0002"),a("); session state is folded from its append-only events ("),s("a",{href:"./adr/0003-sessions-are-append-only-event-logs"},"ADR 0003"),a(").")],-1)),e[10]||(e[10]=s("h2",{id:"modules",tabindex:"-1"},[a("Modules "),s("a",{class:"header-anchor",href:"#modules","aria-label":'Permalink to "Modules"'},"​")],-1)),e[11]||(e[11]=s("p",null,'Solid arrows are module dependencies in the current Gradle build; arrows labelled "planned" are not built in v1.',-1)),(r(),i(l,null,{default:t(()=>[d(n,{id:"mermaid-316",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20android%5B%22app-android%3Cbr%2F%3ECompose%22%5D%20--%3E%20shared%0A%20%20%20%20ios%5B%22app-ios%3Cbr%2F%3ESwiftUI%22%5D%20--%3E%20shared%0A%0A%20%20%20%20shared%5B%22shared%3Cbr%2F%3Eview%20models%20%C2%B7%20iOS%20framework%22%5D%20--%3E%20model%5B%22core%2Fmodel%3Cbr%2F%3Edomain%20types%22%5D%0A%20%20%20%20shared%20--%3E%20engine%5B%22core%2Fengine%3Cbr%2F%3Etimeline%20%C2%B7%20Session%22%5D%0A%20%20%20%20shared%20--%3E%20catalog%5B%22catalog%3Cbr%2F%3Ebundled%20exercises%22%5D%0A%20%20%20%20shared%20--%3E%20local%5B%22data%2Flocal%3Cbr%2F%3ESQLite%20%C2%B7%20repositories%22%5D%0A%20%20%20%20shared%20--%3E%20ftms%5B%22device%2Fftms%3Cbr%2F%3EFTMS%20decoding%22%5D%0A%20%20%20%20shared%20--%3E%20treadmill%5B%22types%2Ftreadmill%3Cbr%2F%3Etreadmill%20logic%22%5D%0A%20%20%20%20engine%20--%3E%20model%0A%20%20%20%20stats%5B%22core%2Fstats%3Cbr%2F%3Esession%20metrics%22%5D%20--%3E%20engine%0A%20%20%20%20local%20--%3E%20stats%0A%20%20%20%20local%20--%3E%20engine%0A%20%20%20%20catalog%20--%3E%20model%0A%20%20%20%20ftms%20--%3E%20model%0A%20%20%20%20treadmill%20--%3E%20engine%0A%20%20%20%20fit%5B%22export%2Ffit%3Cbr%2F%3EFIT%20encoder%22%5D%20--%3E%20model%0A%20%20%20%20i18n%5B%22tools%2Fi18n%3Cbr%2F%3Ebuild-time%20text%22%5D%20-.%20generates%20.-%3E%20catalog%0A%20%20%20%20i18n%20-.%20generates%20.-%3E%20shared%0A%0A%20%20%20%20server%5B%22server%20%C2%B7%20later%2C%20not%20in%20v1%3Cbr%2F%3EJVM%22%5D%20--%3E%20model%0A%20%20%20%20web%5B%22web%20%C2%B7%20later%2C%20not%20in%20v1%3Cbr%2F%3Ebrowser%22%5D%20-.%20planned%20Kotlin%2FJS%20engine%20.-%3E%20engine%0A%20%20%20%20sync%5B%22data%2Fsync%20%C2%B7%20later%2C%20not%20in%20v1%22%5D%20-.%20planned%20phone%20sync%20.-%3E%20local%0A%20%20%20%20sync%20-.%20planned%20sync%20.-%3E%20server%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[a(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=o('<p>Android and iOS both depend on <code>shared</code>; iOS consumes its <code>Shared</code> framework.</p><h2 id="text-and-translations" tabindex="-1">Text and translations <a class="header-anchor" href="#text-and-translations" aria-label="Permalink to &quot;Text and translations&quot;">​</a></h2><p>Every word a person reads is in <code>i18n/messages/&lt;locale&gt;/&lt;namespace&gt;.json</code> (<a href="./adr/0014-text-lives-in-one-json-file-per-language-and-namespace">ADR 0014</a>). At build time <code>tools/i18n</code>, run by the <code>coachpoulpy.i18n</code> Gradle plugin, writes the Android <code>strings.xml</code>, the iOS <code>.strings</code> and <code>.stringsdict</code>, the shared <code>DomainText</code> object (one typed function per <code>domain</code> message, so a wrong id or argument fails the build) and the catalog with its text merged back in (<a href="./adr/0015-catalog-text-lives-in-translation-files">ADR 0015</a>). None of it is committed, and the build fails when a shipped language lacks a message. How to add a string is in <a href="./../i18n/README">the translation files&#39; README</a>.</p><h2 id="storage-and-sync" tabindex="-1">Storage and sync <a class="header-anchor" href="#storage-and-sync" aria-label="Permalink to &quot;Storage and sync&quot;">​</a></h2><p>The phone database is the source of truth and the server is a replica (<a href="./adr/0001-local-first-phone-is-the-source-of-truth">ADR 0001</a>); sync and the website are later work.</p>',5)),(r(),i(l,null,{default:t(()=>[d(n,{id:"mermaid-332",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20phone%5B%22Phone%3Cbr%2F%3Eguest%20%C2%B7%20SQLite%20source%20of%20truth%22%5D%20-.%20%22sign-up%3A%20upload%20local%20database%22%20.-%3E%20server%5B%22Server%20replica%20%C2%B7%20later%2C%20not%20in%20v1%22%5D%0A%20%20%20%20phone%20-.%20%22push%20changes%20with%20base%20versions%22%20.-%3E%20server%0A%20%20%20%20server%20-.%20%22pull%20changes%20since%20cursor%22%20.-%3E%20phone%0A%20%20%20%20web%5B%22Website%20%C2%B7%20later%2C%20not%20in%20v1%3Cbr%2F%3Eonline-first%22%5D%20-.%20%22same%20push%20and%20pull%20calls%22%20.-%3E%20server%0A%20%20%20%20web%20-.-%3E%20buffer%5B%22IndexedDB%3Cbr%2F%3Ebuffers%20running%20Session%20events%22%5D%0A%20%20%20%20phone%20--%3E%20records%5B%22Session%20events%3Cbr%2F%3Eappend-only%22%5D%0A%20%20%20%20records%20-.%20%22sync%20as%20union%3B%20no%20conflicts%22%20.-%3E%20server%0A%20%20%20%20edits%5B%22Workout%20and%20Plan%20edits%22%5D%20-.%20%22on%20conflict%2C%20keep%20both%20versions%22%20.-%3E%20server%0A%20%20%20%20fields%5B%22Small%20fields%22%5D%20-.%20%22latest%20write%20wins%22%20.-%3E%20server%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[a(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=o('<p>Sync follows <a href="./adr/0006-sync-keeps-both-edits">ADR 0006</a>.</p><ul><li>Ids are UUIDv7 made on the device (<a href="./adr/0005-ids-are-uuidv7-made-on-the-device">ADR 0005</a>).</li><li>Workouts and Plans keep both edits; small fields take the latest write (<a href="./adr/0006-sync-keeps-both-edits">ADR 0006</a>).</li><li>The catalog ships with the app and updates without an account (<a href="./adr/0008-curated-catalog-with-stable-slugs">ADR 0008</a>).</li><li>The server&#39;s Postgres schema is its own numbered SQLDelight migrations, applied on start (<a href="./adr/0022-the-servers-schema-is-sqldelight-migrations-on-postgres">ADR 0022</a>).</li></ul><h2 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h2>',3)),(r(),i(l,null,{default:t(()=>[d(n,{id:"mermaid-361",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20source%5B%22Metric%20source%3Cbr%2F%3EFTMS%20treadmill%20in%20v1%22%5D%20--%3E%7Cstreams%7C%20samples%5B%22Timestamped%20Samples%3Cbr%2F%3Espeed%20%C2%B7%20incline%20%C2%B7%20distance%20%C2%B7%20heart%20rate%20%C2%B7%20cadence%22%5D%0A%20%20%20%20samples%20--%3E%7Crecorded%20as%7C%20events%5B%22Session%20events%3Cbr%2F%3ESample%22%5D%0A%20%20%20%20events%20--%3E%7Cfolded%20with%20other%20events%7C%20session%5B%22Session%3Cbr%2F%3Estate%20machine%22%5D%0A%20%20%20%20session%20--%3E%20state%5B%22Session%20state%22%5D%0A%20%20%20%20note%5B%22Samples%20are%20recorded%3B%3Cbr%2F%3Ethey%20do%20not%20advance%20a%20Phase%22%5D%20-.-%3E%20session%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[a(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=o('<p>Treadmills are read-only metric sources in v1 (<a href="./adr/0010-treadmills-are-read-only-metric-sources">ADR 0010</a>).</p><p>On Android a Live recording runs in a connected-device foreground service, from Start until it finishes or is discarded, with an ongoing notification that opens Live and has Pause or Resume and Finish buttons; on Android 14 and later it needs the Bluetooth permission, and without it a timer-only recording runs in the app alone. On iOS the Bluetooth background mode keeps recording on a locked phone, and Kable&#39;s central has a restore identifier so the system relaunches the app for the device&#39;s data after closing it. Guided sessions in the player have neither: they rely on the screen staying on, and on resuming from their events. A dropped link is retried for 60 seconds while the session keeps its timer, and the gap is marked in the samples rather than filled. Many treadmills send only some FTMS fields, so the decoder reads the feature flags first and the UI hides what a machine does not send.</p><h2 id="accounts-and-security" tabindex="-1">Accounts and security <a class="header-anchor" href="#accounts-and-security" aria-label="Permalink to &quot;Accounts and security&quot;">​</a></h2><ul><li>A guest&#39;s data never leaves the phone; the operating system&#39;s file encryption protects it.</li><li>Sign-up pushes the whole local database as a first sync, keeping ids.</li><li>Email and password hashed with Argon2id, plus Sign in with Apple and Google, whose ID tokens the server verifies.</li><li>Every credential resolves to one caller (account, client, scopes) through one http4k filter (<a href="./the-api">the API</a>); routes check scopes, every query is scoped by owner, and coach access is checked against an active coach link on each request (<a href="./adr/0020-every-credential-resolves-to-one-caller">ADR 0020</a>).</li><li>Tokens are opaque and stored hashed: 15-minute access tokens and rotating refresh tokens, in Keychain or Android Keystore on phones and an HttpOnly, SameSite cookie on the website. <code>GET /api/v1/me</code> tells a client who it is. Personal access tokens, then OAuth 2.1 for third-party apps and the MCP server, come with <a href="https://github.com/tkint/coach-poulpy/issues/228" target="_blank" rel="noreferrer">#228</a>.</li><li>The landing site, the web app and the API each have their own hostname and container: <code>coach-poulpy.com</code>, <code>app.coach-poulpy.com</code>, <code>api.coach-poulpy.com</code> (<a href="./adr/0021-the-landing-site-the-app-and-the-api-have-their-own-hostname">ADR 0021</a>).</li><li>Health data is sensitive under the GDPR: consent at sign-up, export as JSON and FIT, full deletion, hosting in the EU; token reads of health data are logged.</li></ul><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>The first release needs no server. Android phones install the signed APK from CI; iPhones need Xcode (7-day installs with a free account) or TestFlight with a paid Apple Developer membership. The server builds into one JVM program in a Docker image, published with each release and run on one server with Docker (<a href="./adr/0019-the-server-runs-with-docker-compose-on-one-server">ADR 0019</a>). <a href="./deploying-the-server">Deploying the server</a> runs it there behind a Caddy that other apps can share.</p>',6))])}const C=h(u,[["render",m]]);export{y as __pageData,C as default};
